select left(stem,120) from questions q join subject_groups g on g.id=q.subject_group_id where g.code='statistics' and (stem ilike '%P(A ∪ B)%' or stem ilike '%independent events%' or stem ilike '%variance of a binomial%' or stem ilike '%box plot%' or stem ilike '%boxplot%' or stem ilike '%2, 4, 6, 8, 10%' or stem ilike '%sample variance%' or stem ilike '%electricity bill%' or stem ilike '%confidence interval%' or stem ilike '%sample size%');
